def transform(grid):
    out = [row[:] for row in grid]
    # Fill internal gaps and extend verticals from gap columns upward to the top edge.
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v]
        if not nz:
            continue
        # For gaps enclosed by nonzero cells, fill using nearest side's color.
        for c in range(nz[0] + 1, nz[-1]):
            if row[c] == 0:
                left = next((row[k] for k in range(c-1, -1, -1) if row[k]), 0)
                right = next((row[k] for k in range(c+1, len(row)) if row[k]), 0)
                # gap on change between two color runs takes color of right run
                out[r][c] = right if right else left
                # extend the completed horizontal line vertically upward
                for rr in range(r):
                    if out[rr][c] == 0:
                        out[rr][c] = out[r][c]
    return out
